def arb(lang):
    d = {"@@locale": lang}
    for row in T:
        key, en, ar = row[0], row[1], row[2]
        d[key] = en if lang == "en" else ar
        if lang == "en" and len(row) > 3:
            d["@" + key] = {"placeholders": row[3]}
    return d
here = os.path.dirname(os.path.abspath(__file__))
for lang in ("en", "ar"):
    with open(os.path.join(here, "..", "lib", "l10n", f"app_{lang}.arb"), "w", encoding="utf-8") as f:
        json.dump(arb(lang), f, ensure_ascii=False, indent=2)
        f.write("\n")
print(len(T), "keys")
